/**
 * THE PARITY PROOF for narrower branches (mixed-visibility DESIGN §4.3 "Narrower branches (phase
 * 3F)", `docs/security/private-repos.md` §20): every `branch_key__*` vector in
 * `forge-contracts/vectors/` (generated by `tools/private-repos-vectors/branch_key.py`), run against
 * `./branch-key`. forge-core `private::branch_key::conformance` runs the same files, with the same
 * input and output shapes. Unknown input keys are refused at every depth (a letter's `body` is the
 * letter itself, any JSON, which the parser judges).
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { expand } from '@noble/hashes/hkdf.js'
import { hmac } from '@noble/hashes/hmac.js'
import { sha256 as nobleSha256 } from '@noble/hashes/sha2.js'
import { describe, expect, it } from 'vitest'

import {
  BranchKey,
  BranchKeys,
  BranchRing,
  V6,
  foldBranchLetters,
  openBranchPack,
  parseBranchKeyLetter,
  sniffBranchKcv,
  type BranchLetterIgnored,
  type BranchLetterIn,
} from './branch-key'
import { bytesToHex, concat, hexToBytes, sha256, utf8 } from './bytes'
import { TooLargeError, docAdIn, type PrivateDoc, type StoredPrivateDoc } from './doc'
import { compareBytes, privateId } from './ids'
import { realValues, type RefUpdateType } from './members-ref'
import { PackError, sniff } from './pack'
import { sealBranchPackWith, sealBranchRefWith } from './testing'
import { MalformedError, encodeTlv, type DocFields, type PrivateDocType } from './tlv'

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly description: string
  readonly case: string
  readonly rules: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
/** The vector case this harness runs (forge-core `branch_key::conformance::CASE`); the rules harness skips it. */
const CASE = 'branch_key'
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith(`${CASE}__`) && f.endsWith('.json'))
  .sort()

// ---------------------------------------------------------------------------------------------
// Input allow-list
// ---------------------------------------------------------------------------------------------

type Shape =
  | { readonly kind: 'leaf' }
  | { readonly kind: 'any' }
  | { readonly kind: 'each'; readonly of: Shape }
  | { readonly kind: 'values'; readonly of: Shape }
  | { readonly kind: 'object'; readonly fields: { readonly [k: string]: Shape } }

const LEAF: Shape = { kind: 'leaf' }
const ANY: Shape = { kind: 'any' }
const each = (of: Shape): Shape => ({ kind: 'each', of })
const values = (of: Shape): Shape => ({ kind: 'values', of })
const object = (fields: { readonly [k: string]: Shape }): Shape => ({ kind: 'object', fields })
const leafFields = (...keys: string[]) => Object.fromEntries(keys.map((k) => [k, LEAF]))

/** forge-core `DocHeader` (its `tagName` aside: a release is not a ref update) and `enc`. */
const DOC = object(
  leafFields(
    'type', 'vis', 'ownerId', 'epoch', 'number', 'targetId', 'patchId', 'refNameHash', 'newOid', 'prevOid',
    'force', 'baseRefNameHash', 'sourceRefNameHash', 'id', 'createdAtBlockHeight', 'updatedAtBlockHeight', 'enc',
  ),
)
const LETTER = object({ ...leafFields('id', 'height', 'owner'), body: ANY })
const SHAPE = object({
  ...leafFields(
    'op', 'repoId', 'key', 'keys', 'names', 'gen', 'type', 'ownerId', 'refName', 'newOid', 'prevOid', 'force', 'salt',
    'nonce', 'plain', 'fileId', 'segLog2', 'sealed', 'sizeBytes', 'head',
  ),
  context: object({ letters: each(LETTER), audience: values(LEAF) }),
  doc: DOC,
  letters: each(LETTER),
})

function isObj(v: Json | undefined): v is Obj {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

/** Refuse any key the shape does not list, at every depth. */
function checkShape(value: Json, shape: Shape, path: string): void {
  switch (shape.kind) {
    case 'any':
      return
    case 'leaf': {
      const scalar = (x: Json) => !isObj(x) && !Array.isArray(x)
      expect(Array.isArray(value) ? value.every(scalar) : scalar(value), `${path}: expected a scalar`).toBe(true)
      return
    }
    case 'each':
      expect(Array.isArray(value), `${path}: expected an array`).toBe(true)
      for (const [i, x] of (value as Json[]).entries()) checkShape(x, shape.of, `${path}[${i}]`)
      return
    case 'values':
      expect(isObj(value), `${path}: expected an object`).toBe(true)
      for (const [k, x] of Object.entries(value as Obj)) checkShape(x, shape.of, `${path}.${k}`)
      return
    case 'object': {
      expect(isObj(value), `${path}: expected an object`).toBe(true)
      const o = value as Obj
      expect(Object.keys(o).filter((k) => !(k in shape.fields)), `${path}: unknown keys`).toEqual([])
      for (const [k, x] of Object.entries(o)) checkShape(x, shape.fields[k] as Shape, `${path}.${k}`)
      return
    }
  }
}

// ---------------------------------------------------------------------------------------------
// Input conversion
// ---------------------------------------------------------------------------------------------

const str = (o: Obj, k: string): string => {
  const v = o[k]
  if (typeof v !== 'string') throw new TypeError(`${k}: expected a string`)
  return v
}
const num = (o: Obj, k: string): number => {
  const v = o[k]
  if (typeof v !== 'number') throw new TypeError(`${k}: expected a number`)
  return v
}
const obj = (o: Obj, k: string): Obj => {
  const v = o[k]
  if (!isObj(v)) throw new TypeError(`${k}: expected an object`)
  return v
}
const arr = (o: Obj, k: string): Obj[] => {
  const v = o[k]
  if (!Array.isArray(v) || !v.every(isObj)) throw new TypeError(`${k}: expected an array of objects`)
  return v as Obj[]
}
const strs = (o: Obj, k: string): string[] => {
  const v = o[k]
  if (!Array.isArray(v) || !v.every((x) => typeof x === 'string')) throw new TypeError(`${k}: expected an array of strings`)
  return v as string[]
}
const hex = (o: Obj, k: string): Uint8Array => hexToBytes(str(o, k))
const optHex = (o: Obj, k: string): Uint8Array | undefined => (k in o ? hex(o, k) : undefined)
const bkey = (h: string): BranchKey => BranchKey.fromBytes(hexToBytes(h))
const byCodePoint = (a: string, b: string): number => compareBytes(utf8(a), utf8(b))

function storedDoc(d: Obj): StoredPrivateDoc {
  return {
    type: str(d, 'type') as PrivateDocType,
    vis: 'vis' in d ? (str(d, 'vis') as 'public' | 'private') : undefined,
    ownerId: privateId(str(d, 'ownerId')),
    epoch: num(d, 'epoch'),
    number: 'number' in d ? num(d, 'number') : undefined,
    targetId: optHex(d, 'targetId'),
    patchId: optHex(d, 'patchId'),
    refNameHash: optHex(d, 'refNameHash'),
    newOid: optHex(d, 'newOid'),
    prevOid: optHex(d, 'prevOid'),
    force: d['force'] === true,
    baseRefNameHash: optHex(d, 'baseRefNameHash'),
    sourceRefNameHash: optHex(d, 'sourceRefNameHash'),
    id: 'id' in d ? privateId(str(d, 'id')) : undefined,
    createdAtBlockHeight: 'createdAtBlockHeight' in d ? num(d, 'createdAtBlockHeight') : undefined,
    updatedAtBlockHeight: 'updatedAtBlockHeight' in d ? num(d, 'updatedAtBlockHeight') : undefined,
    enc: hex(d, 'enc'),
  }
}

function errorJson(e: unknown): Json {
  if (e instanceof MalformedError) return { error: 'malformed' }
  if (e instanceof TooLargeError) return { error: 'tooLarge' }
  if (e instanceof PackError) return { error: e.code }
  throw e
}

/** The letters as the fold takes them, and the ignored ones the parse refused (forge-core `parse_letters`). */
function parseLetters(letters: readonly Obj[]): { ok: BranchLetterIn[]; bad: { id: string; reason: BranchLetterIgnored }[] } {
  const ok: BranchLetterIn[] = []
  const bad: { id: string; reason: BranchLetterIgnored }[] = []
  for (const l of letters) {
    const parsed = parseBranchKeyLetter(l['body'])
    if (parsed === 'malformed') bad.push({ id: str(l, 'id'), reason: 'malformed' })
    else if (parsed !== null) ok.push({ id: str(l, 'id'), height: num(l, 'height'), letter: parsed })
  }
  return { ok, bad }
}

async function foldJson(repoId: Uint8Array, letters: readonly Obj[]): Promise<Json> {
  const { ok, bad } = parseLetters(letters)
  const { branches, ignored } = foldBranchLetters(ok)
  const all = [...bad, ...ignored]
  // the reference lists ignored letters in fold order, which is the input's height order
  const order = new Map(letters.map((l) => [str(l, 'id'), num(l, 'height')]))
  all.sort((a, b) => (order.get(a.id) as number) - (order.get(b.id) as number) || byCodePoint(a.id, b.id))
  const out: Json[] = []
  for (const b of branches.values()) {
    const kcvs: string[] = []
    for (const [g, k] of b.keys.entries()) kcvs.push(bytesToHex((await BranchKeys.derive(repoId, g, k)).kcv4))
    out.push({
      name: b.name,
      group: b.audience.group,
      people: [...b.audience.also],
      issuedAt: Object.fromEntries(b.issuedAt.map((h, g) => [String(g), h])),
      letters: [...b.letters],
      holders: [...b.holders],
      kcvs,
      gen: b.gen,
    })
  }
  return { branches: out, ignored: all.map((i) => ({ id: i.id, reason: i.reason })) }
}

async function run(v: Vector): Promise<Json> {
  const inp = v.input
  const repoId = optHex(inp, 'repoId') as Uint8Array
  switch (str(inp, 'op')) {
    case 'kdf': {
      const raw = hex(inp, 'key')
      const k = await BranchKeys.derive(repoId, 0, BranchKey.fromBytes(raw))
      // the raw PRK and K_brref, which non-extractable WebCrypto keys cannot reveal, recomputed
      // from their definitions; the KCV and the name hashes are the production keys'
      const prk = hmac(nobleSha256, repoId, raw)
      const sub = (label: string, n: number) => expand(nobleSha256, prk, concat(utf8(`dash-forge/v2/${label}`), new Uint8Array([0])), n)
      expect(bytesToHex(sub('br-kcv', 14))).toBe(bytesToHex(k.kcv))
      const refNameHashes: string[] = []
      for (const n of strs(inp, 'names')) refNameHashes.push(bytesToHex(await k.refNameHash(n)))
      return { kcv: bytesToHex(k.kcv), prk: bytesToHex(prk), refKey: bytesToHex(sub('br-ref', 32)), refNameHashes }
    }
    case 'seal': {
      const gen = num(inp, 'gen')
      const k = await BranchKeys.derive(repoId, gen, bkey(str(inp, 'key')))
      const owner = hex(inp, 'ownerId')
      const type = str(inp, 'type') as RefUpdateType
      const name = str(inp, 'refName')
      const newOid = hex(inp, 'newOid')
      const prevOid = optHex(inp, 'prevOid')
      const salt = hex(inp, 'salt')
      const force = inp['force'] === true
      let sealed
      try {
        sealed = await sealBranchRefWith(k, owner, { type, name, newOid, prevOid, force }, salt, hex(inp, 'nonce'))
      } catch (e) {
        return errorJson(e)
      }
      // the TLV and the AD, recomputed from their definitions rather than read back from the seal
      const header: PrivateDoc = {
        type,
        vis: 'public',
        ownerId: owner,
        epoch: gen,
        refNameHash: await k.refNameHash(name),
        newOid: sealed.newOid,
        prevOid: sealed.prevOid,
        force,
      }
      const real = (o: Uint8Array | undefined) => (o === undefined || o.every((b) => b === 0) ? undefined : o)
      const fields: DocFields = { refName: name, newOid: real(newOid), prevOid: real(prevOid), oidSalt: salt }
      const doc: { [k: string]: Json } = {
        epoch: sealed.epoch,
        refNameHash: bytesToHex(sealed.refNameHash),
        newOid: bytesToHex(sealed.newOid),
        force: sealed.force,
      }
      if (sealed.prevOid !== undefined) doc['prevOid'] = bytesToHex(sealed.prevOid)
      expect(bytesToHex(sealed.salt)).toBe(bytesToHex(salt))
      expect(sealed.type).toBe(type)
      return {
        doc,
        tlv: bytesToHex(encodeTlv(Object.fromEntries(Object.entries(fields).filter(([, x]) => x !== undefined)) as DocFields)),
        ad: bytesToHex(docAdIn(header, repoId, V6)),
        enc: bytesToHex(sealed.enc),
      }
    }
    case 'open': {
      const ctx = obj(inp, 'context')
      const audience = obj(ctx, 'audience')
      const ring = await BranchRing.create(repoId, foldBranchLetters(parseLetters(arr(ctx, 'letters')).ok), (b) =>
        isObj(audience) && Array.isArray(audience[b.name]) ? (audience[b.name] as string[]).map((h) => hexToBytes(h)) : [],
      )
      const { enc, ...header } = storedDoc(obj(inp, 'doc'))
      const opened = await ring.open(header, enc)
      switch (opened.status) {
        case 'readable': {
          const r = await realValues(header, opened.fields)
          if (r === null) throw new Error('checked by open')
          const ref: { [k: string]: Json } = { name: r.name, newOid: bytesToHex(r.newOid) }
          if (r.prevOid !== undefined) ref['prevOid'] = bytesToHex(r.prevOid)
          return { status: 'readable', ref, alerts: r.alerts.map((a) => ({ field: a.field, kind: a.kind })), branch: r.name, gen: header.epoch }
        }
        case 'unreadable':
          return { status: 'unreadable', reason: opened.reason }
        case 'malformed':
          return { status: 'malformed' }
      }
      throw new Error('unreachable')
    }
    case 'packSeal': {
      const k = await BranchKeys.derive(repoId, 0, bkey(str(inp, 'key')))
      const sealed = await sealBranchPackWith(k, hex(inp, 'plain'), hex(inp, 'fileId'), num(inp, 'segLog2'))
      const out: { [k: string]: Json } = { header: bytesToHex(sealed.subarray(0, 36)), sha256: bytesToHex(await sha256(sealed)) }
      if (isObj(v.expected) && 'sealed' in v.expected) out['sealed'] = bytesToHex(sealed)
      return out
    }
    case 'packOpen': {
      const keys: BranchKeys[] = []
      for (const h of strs(inp, 'keys')) keys.push(await BranchKeys.derive(repoId, 0, bkey(h)))
      try {
        return { plain: bytesToHex(await openBranchPack(hex(inp, 'sealed'), num(inp, 'sizeBytes'), keys)) }
      } catch (e) {
        return errorJson(e)
      }
    }
    case 'sniff': {
      const head = hex(inp, 'head')
      const kcv = sniffBranchKcv(head)
      if (kcv !== null) return { kind: 'branch', kcv: bytesToHex(kcv) }
      const h = sniff(head)
      switch (h.kind) {
        case 'plain':
        case 'short':
          return { kind: h.kind }
        case 'sealed':
          return { kind: 'sealed', epoch: h.epoch }
        case 'otherVersion':
          // a DFPK 0x03 head too short for its KCV prefix
          return h.version === 3 ? { kind: 'short' } : { kind: 'otherVersion', version: h.version }
      }
      throw new Error('unreachable')
    }
    case 'fold':
      return foldJson(repoId, arr(inp, 'letters'))
    default:
      throw new Error(`vector ${v.name}: branch_key op ${str(inp, 'op')}`)
  }
}

describe('narrower branch conformance vectors', () => {
  const vectors: Vector[] = FILES.map((f) => JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector)
  const ran = new Map<string, number>()

  for (const v of vectors) {
    it(`${v.case} :: ${v.name}`, async () => {
      expect(v.case).toBe(CASE)
      expect(v.rules).toBe('v2')
      checkShape(v.input, SHAPE, `${v.name}.input`)
      expect(await run(v)).toEqual(v.expected)
      const op = str(v.input, 'op')
      ran.set(op, (ran.get(op) ?? 0) + 1)
    })
  }

  it('ran every branch_key vector, every op', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(52)
    for (const op of ['kdf', 'seal', 'open', 'packSeal', 'packOpen', 'sniff', 'fold']) expect(ran.get(op) ?? 0, op).toBeGreaterThanOrEqual(1)
    expect([...ran.values()].reduce((a, b) => a + b, 0)).toBe(FILES.length)
  })
})
